Guided/structured JSON decoding (`response_format`) guarantees parseable `{score, reason}` outputs with bounded retries:
```python
async def score_batch(vllm_client, traces, rubric_prefix, max_retries=2):
    results = []
    for trace in traces:
        for attempt in range(max_retries + 1):
            try:
                resp = await vllm_client.generate(
                    prompt=f"{rubric_prefix}\nTrace:{trace['payload']}",
                    extra_body={"guided_json": JUDGE_SCHEMA}, timeout=15.0
                )
                results.append(json.loads(resp.text))
                break
            except (TimeoutError, json.JSONDecodeError):
                if attempt == max_retries:
                    results.append({"score": None, "error": "judge_failed"})
    return results
